// Consistent hashing implementation (simplified)
const crypto = require('crypto');

class ConsistentHashRing {
  constructor(virtualNodes = 100) {
    this.virtualNodes = virtualNodes; // more = better distribution
    this.ring = new Map();            // hash -> nodeName
    this.sortedHashes = [];           // sorted array of hashes
  }

  hash(key) {
    return parseInt(
      crypto.createHash('md5').update(key).digest('hex').slice(0, 8),
      16
    );
  }

  addNode(nodeName) {
    for (let i = 0; i < this.virtualNodes; i++) {
      const virtualKey = `${nodeName}#${i}`;
      const h = this.hash(virtualKey);
      this.ring.set(h, nodeName);
      this.sortedHashes.push(h);
    }
    this.sortedHashes.sort((a, b) => a - b);
  }

  removeNode(nodeName) {
    for (let i = 0; i < this.virtualNodes; i++) {
      const h = this.hash(`${nodeName}#${i}`);
      this.ring.delete(h);
    }
    this.sortedHashes = this.sortedHashes.filter(h => this.ring.has(h));
  }

  getNode(key) {
    if (this.sortedHashes.length === 0) throw new Error('Ring is empty');
    const h = this.hash(key);
    // Find first hash >= h (clockwise on the ring)
    const idx = this.sortedHashes.findIndex(pos => pos >= h);
    const ringPos = idx === -1 ? 0 : idx; // wrap around
    return this.ring.get(this.sortedHashes[ringPos]);
  }
}

// Usage
const ring = new ConsistentHashRing(150);
['node-a', 'node-b', 'node-c'].forEach(n => ring.addNode(n));

console.log(ring.getNode('user:1001'));  // e.g., 'node-b'
console.log(ring.getNode('order:555')); // e.g., 'node-a'

// Adding a node only re-routes ~1/N = ~33% of keys
ring.addNode('node-d');
console.log(ring.getNode('user:1001')); // may now be 'node-d'

// Replication and partitioning strategy selection guide

// REPLICATION TOPOLOGIES:
// Leader-follower:  simple, read scale, failover built-in
//   Use: most RDBMS (Postgres, MySQL), MongoDB, Redis Sentinel
//   Risk: leader is write bottleneck; replication lag on reads

// Multi-leader:     write availability across regions, lower write latency
//   Use: multi-datacenter active-active, CouchDB, conflict-free mobile sync
//   Risk: write conflicts require resolution strategy

// Leaderless:       highest availability, no single write bottleneck
//   Use: Cassandra (W+R>N quorum), DynamoDB, Riak
//   Risk: eventual consistency by default; sloppy quorum possible

// QUORUM FORMULA (leaderless):
// N=3, W=2, R=2: W+R=4 > 3 — reads always overlap with writes
// N=5, W=3, R=3: W+R=6 > 5 — tolerates 2 node failures
// N=3, W=1, R=1: W+R=2 = N — NOT a quorum; possible stale reads

// PARTITIONING STRATEGIES:
// Range: good for sorted scans; hotspot risk on sequential keys
//   Fix hotspot: prefix timestamp keys with random bucket prefix

// Hash: even distribution; no range scans across partitions
//   Use: user_id, order_id — uniform random-access keys

// Consistent hash: hash + easy rebalancing
//   Use: cache clusters (Redis), Cassandra, DynamoDB
//   Virtual nodes (vnodes) improve balance with few physical nodes
